def _digits_needed(order, catalog) -> int:
    """An upper bound on the significant digits any intermediate value needs."""
    biggest = 0
    for sku, quantity in order.lines:
        price = Decimal(catalog[sku].price)
        digits = len(str(abs(int(quantity)))) + max(price.adjusted() + 1, 1)
        biggest = max(biggest, digits)
    # products carry 2 price decimals and up to 4 rate decimals; sums over
    # the lines add at most len(lines) worth of carry digits.
    return biggest + len(str(len(order.lines))) + 16


def _price_order(order, catalog) -> Quote:
    lines = []
    for sku, quantity in order.lines:
        product = catalog[sku]
        unit = money(product.price)
        gross = money(unit * quantity)
        disc = money(gross * volume_rate(quantity))
        net = money(gross - disc)
        lines.append(QuoteLine(sku, quantity, unit, gross, money(-disc), net))
    subtotal = money(sum((l.net for l in lines), ZERO))
    order_disc = money(subtotal * Decimal("0.03")) if subtotal >= Decimal("500.00") else ZERO
    # Pennies as integral Decimals: int() on a huge Decimal is very slow.
    shares = allocate(order_disc.scaleb(2), [l.net.scaleb(2) for l in lines])
    tax = ZERO
    for line, share in zip(lines, shares):
        taxable = line.net - Decimal(share) / 100
        tax += money(taxable * TAX_RATES[catalog[line.sku].tax])
    tax = money(tax)
    total = money(subtotal - order_disc + tax)
    return Quote(lines, subtotal, money(-order_disc), tax, total)
